// Keeps the whole editor on this device. Every file is checked against the release manifest before it is stored, so a
// failed or tampered download leaves the working copy in place. offline-manifest.js is generated by tools/build.mjs.
import {sha256Hex} from './hashing.js';
import {byteRangeResponse} from './offline-cache.js';
import {archive, files, release} from './offline-manifest.js';

const cachePrefix = 'editor-';
const shellCacheName = `${cachePrefix}shell-${release}`;
// Named by content, so a release with the same map data reuses it instead of downloading it again.
const archiveCacheName = `${cachePrefix}archive-${archive.sha256}`;

const scopedURL = path => new URL(path, self.registration.scope).href;

// cache: 'reload' skips the browser's HTTP cache, which could hold a file from another release.
async function verifiedResponse({path, sha256}) {
  const response = await fetch(scopedURL(path), {cache: 'reload'});
  if (!response.ok) throw new Error(`${path}: HTTP ${response.status}`);
  const actualHash = await sha256Hex(await response.clone().arrayBuffer());
  if (actualHash !== sha256) throw new Error(`${path} differs from the release manifest`);
  return response;
}

async function storeRelease() {
  const shellCache = await caches.open(shellCacheName);
  for (const file of files) await shellCache.put(scopedURL(file.path), await verifiedResponse(file));
  const archiveCache = await caches.open(archiveCacheName);
  const hasArchive = await archiveCache.match(scopedURL(archive.path));
  if (!hasArchive) await archiveCache.put(scopedURL(archive.path), await verifiedResponse(archive));
}

async function storeReleaseOrCleanUp() {
  try {
    await storeRelease();
  } catch (error) {
    await caches.delete(shellCacheName);
    throw error;
  }
}

async function removeOtherReleases() {
  const cacheNames = await caches.keys();
  const isObsolete = name => name.startsWith(cachePrefix) && name !== shellCacheName && name !== archiveCacheName;
  await Promise.all(cacheNames.filter(isObsolete).map(name => caches.delete(name)));
  await self.clients.claim();
}

async function offlineResponse(request, url) {
  const path = url.pathname.slice(new URL(self.registration.scope).pathname.length);
  if (path === archive.path) {
    const storedArchive = await (await caches.open(archiveCacheName)).match(scopedURL(archive.path));
    return storedArchive ? byteRangeResponse(storedArchive, request.headers.get('Range')) : fetch(request);
  }
  const shellCache = await caches.open(shellCacheName);
  const storedPath = path === '' ? 'index.html' : path;
  return (await shellCache.match(scopedURL(storedPath))) ?? fetch(request);
}

self.addEventListener('install', event => event.waitUntil(storeReleaseOrCleanUp()));
self.addEventListener('activate', event => event.waitUntil(removeOtherReleases()));
// A new release waits until the editor asks for it, because taking over could reload the page during an edit.
self.addEventListener('message', event => {
  if (event.data?.type === 'activate-update') self.skipWaiting();
});
self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);
  const isOwnRead = event.request.method === 'GET' && url.href.startsWith(self.registration.scope);
  if (isOwnRead) event.respondWith(offlineResponse(event.request, url));
});
